const menu=document.querySelector('.burger'),nav=document.querySelector('.head .nav');
function closeMenu(){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Открыть меню')}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');nav.classList.toggle('open',open)});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
const lightbox=document.querySelector('#lightbox');let activePhoto=0,visiblePhotos=[];
function updatePhoto(){const b=visiblePhotos[activePhoto];if(!b)return;const im=lightbox.querySelector('img');im.src=b.dataset.photo;im.alt=b.querySelector('img').alt;document.querySelector('#photo-count').textContent=`${activePhoto+1} / ${visiblePhotos.length}`}
document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{visiblePhotos=[...document.querySelectorAll('[data-photo]')].filter(x=>!x.closest('[hidden]'));activePhoto=visiblePhotos.indexOf(b);updatePhoto();lightbox.showModal()}));
function stepPhoto(n){if(visiblePhotos.length){activePhoto=(activePhoto+n+visiblePhotos.length)%visiblePhotos.length;updatePhoto()}}
document.querySelectorAll('[data-lightbox-step]').forEach(b=>b.addEventListener('click',()=>stepPhoto(Number(b.dataset.lightboxStep))));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if(lightbox?.open){if(e.key==='ArrowRight')stepPhoto(1);if(e.key==='ArrowLeft')stepPhoto(-1)}});document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close')?.addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
document.querySelectorAll('[data-scroll]').forEach(b=>b.addEventListener('click',()=>{const r=document.querySelector('.reviews');if(r)r.scrollBy({left:Number(b.dataset.scroll)*(r.querySelector('.review').getBoundingClientRect().width+24),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}));
const search=document.querySelector('#price-search');let category='all';const normal=s=>s.toLocaleLowerCase('ru').replaceAll('ё','е').trim();
function filterPrices(){const q=normal(search?.value||'');let count=0;document.querySelectorAll('#price-results .price-group').forEach(g=>{let shown=0;g.querySelectorAll('.price-row').forEach(r=>{const matches=(category==='all'||g.dataset.category===category)&&normal(r.dataset.search).includes(q);r.hidden=!matches;if(matches)shown++});g.hidden=shown===0;count+=shown});const label=document.querySelector('#results-count');if(label)label.textContent=`Найдено услуг: ${count}`;const empty=document.querySelector('#empty-search');if(empty)empty.hidden=count>0}
search?.addEventListener('input',filterPrices);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});filterPrices()}));document.querySelector('#clear-search')?.addEventListener('click',()=>{search.value='';category='all';document.querySelectorAll('[data-filter]').forEach(x=>{const on=x.dataset.filter==='all';x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))});filterPrices();search.focus()});
document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.addEventListener('click',()=>{const type=b.dataset.galleryFilter;document.querySelectorAll('[data-gallery-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('[data-gallery-category]').forEach(x=>x.hidden=type!=='all'&&type!==x.dataset.galleryCategory)}));
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const obs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pending');obs.unobserve(e.target)}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(e=>{e.classList.add('pending');obs.observe(e)})}
